import type {Shot,Storyboard,Narration} from '../core/schemas.js';
import {hash} from '../core/utils.js';
import {samplePhysicalPerformance} from '../animation/compiler.js';
import {actorProfile} from '../actors/model.js';
import {actorViewActingClock} from '../actors/view-acting-clock.js';
import {sourceActor} from './source-actor.js';
import {boundProp} from './prop-owner.js';
import {validateSourceOwnershipTimelines,sourceOwnershipFrame,sourceOwnershipBoundary} from './source-ownership.js';
import {validateSourceWorld} from './source-world.js';
import {validateSourceGripWorld} from './source-grip-world.js';
import {OwnershipPaintSchema,type OwnershipPaint} from './ownership-paint-schemas.js';
import {bakeOwnership,type OwnershipBake} from './ownership-bake.js';
import type {SourceOwnership} from './source-ownership-schemas.js';

export const OWNERSHIP_RENDER_VERSION='canonical-ownership-render-1';
export interface CompiledOwnership {
  version:typeof OWNERSHIP_RENDER_VERSION;source:SourceOwnership;paint:OwnershipPaint;bake:OwnershipBake;
  aliases:Array<{actorId:string;propId:string;svgId:string;hand:'left'|'right';handSvgId:string;slotSvgId:string}>;
  shotHash:string;sourceHash:string;paintHash:string;motionVerified:false;productionApproval:false;
}
const fail=(shot:Shot,message:string):never=>{throw new Error(`${shot.id}: needs-source-prop-binding: ownership render ${message}`);};

/** Candidate compilation on canonical original source, not a production gate
 * override. Called only when a tester or future complete renderer requests it.
 * Current production entry still rejects unaccepted original ownership. */
export function compileSourceOwnership(shot:Shot,board:Storyboard,narration:Narration,actorBreakpoints:readonly number[]=[]):ReadonlyMap<string,CompiledOwnership>{
  if(!shot.cinematic?.sourceOwnership?.length)return fail(shot,'requires explicit original ownership');
  if(board.shots.filter(s=>s.id===shot.id).length!==1||hash(board.shots.find(s=>s.id===shot.id))!==hash(shot))return fail(shot,'requires the authoritative complete storyboard');
  // This is an immutable in-memory source snapshot for the synchronous bake.
  // No files, providers, approval flags or outside state are changed.
  const original=structuredClone(board),voice=structuredClone(narration),canonical=original.shots.find(s=>s.id===shot.id)!;
  validateSourceOwnershipTimelines(canonical,original,voice);
  validateSourceWorld(canonical,original,voice);
  const sources=canonical.cinematic!.sourceOwnership!,paints=canonical.cinematic!.ownershipPaint??[];
  if(paints.length!==sources.length||new Set(paints.map(p=>p.sourceId)).size!==paints.length)return fail(shot,'every entity requires one explicit depth plan');
  const allAliases=sources.flatMap(s=>s.grips.map(g=>JSON.stringify([g.actorId,g.propId])));
  const propIds=sources.flatMap(s=>s.grips.map(g=>g.propId));
  if(new Set(propIds).size!==propIds.length)return fail(shot,'physical prop alias IDs must be unambiguous across the visible cast');
  if(canonical.cinematic!.propBindings.length!==allAliases.length||canonical.cinematic!.propBindings.some(b=>!b.ownerId||!allAliases.includes(JSON.stringify([b.ownerId,b.propId]))))
    return fail(shot,'mixed unregistered/local prop rendering is not supported by this candidate; preserve and report the missing physical binding');
  const result=new Map<string,CompiledOwnership>();
  for(const source of sources){
    const matches=paints.filter(p=>p.sourceId===source.id);if(matches.length!==1)return fail(shot,'missing entity depth plan');
    const paint=OwnershipPaintSchema.parse(matches[0]),part=canonical.visualization!.parts.find(p=>p.id===source.partId)!;
    if(paint.grips.length!==source.grips.length||paint.grips.some(g=>!source.grips.some(s=>s.id===g.gripId)))return fail(shot,'depth plan must name every actual original grip exactly once');
    for(const painted of paint.grips){
      const grip=source.grips.find(g=>g.id===painted.gripId)!;
      const offset={x:(painted.anchor.x-.5)*part.width*canonical.cinematic!.performance.stage.width,y:(painted.anchor.y-.5)*part.height*canonical.cinematic!.performance.stage.height};
      if(Math.hypot(offset.x-grip.gripOffset.x,offset.y-grip.gripOffset.y)>1e-6)return fail(shot,'own authored viewport grip anchor differs from the actual stage grip offset');
      const actor=sourceActor(canonical,grip.actorId);
      if(actor.actions.filter(a=>a.sourceManipulation?.sourceId===grip.sourceId&&a.sourceManipulation.gestureId===grip.gestureId).some(a=>a.target?.anchor==='center'&&(painted.anchor.x!==.5||painted.anchor.y!==.5)))
        return fail(shot,'an off-center grip cannot claim a center action target');
    }
    if(paint.sourceRefs.some(ref=>!part.sourceRefs.some(r=>hash(r)===hash(ref))))return fail(shot,'depth plan lost canonical entity evidence');
    for(const slice of original.shots.filter(s=>s.startMs<source.endMs&&s.endMs>source.startMs))
      if(slice.cinematic?.ownershipPaint?.filter(p=>p.sourceId===source.id&&hash(p)===hash(paint)).length!==1)return fail(slice,'entity depth plan changed at a camera cut');
    for(const phase of source.phases.filter(p=>p.kind!=='world'))validateSourceGripWorld(canonical,part,phase.startMs,phase.endMs,{startMs:source.startMs,endMs:source.endMs});
    // Check every full-original transfer, even if this camera starts later.
    // Never smooth a source discontinuity or start a new contact at the cut.
    for(const transition of source.transitions)sourceOwnershipBoundary(canonical,source.id,transition.id,original,voice);
    const aliases=source.grips.map(grip=>{
      const binding=canonical.cinematic!.propBindings.find(b=>b.ownerId===grip.actorId&&b.propId===grip.propId&&b.partId===source.partId)!;
      const owned=boundProp(canonical,binding);
      return {actorId:grip.actorId,propId:grip.propId,svgId:owned.svgId,hand:grip.hand,handSvgId:`${owned.prefix}hand-${grip.hand}`,slotSvgId:`${owned.prefix}hand-${grip.hand}-prop-slot`};
    });
    const people=new Map(source.grips.map(g=>{
      const actor=sourceActor(canonical,g.actorId),clock=actorViewActingClock(original,canonical,g.actorId);
      if(!clock?.manipulationMotion)return fail(shot,'missing actual original person clock');
      return [g.actorId,{actor,profile:actorProfile(actor.character),clock}] as const;
    }));
    const resolve=(global:number)=>{
      const frame=sourceOwnershipFrame(canonical,source.id,global,original,voice),frames=new Map<string,ReturnType<typeof samplePhysicalPerformance>>();
      const palms=Object.fromEntries(source.grips.map(g=>{
        let body=frames.get(g.actorId);
        if(!body){const owned=people.get(g.actorId)!;body=samplePhysicalPerformance(owned.actor.performance,owned.profile,global-canonical.startMs,owned.clock);frames.set(g.actorId,body);}
        return [g.id,body.hands[g.hand]] as const;
      }));
      return {timeMs:global,center:frame.center,palms,activeGripIds:frame.grips.map(g=>g.gripId),...(frame.authorityGripId===undefined?{}:{authorityGripId:frame.authorityGripId})};
    };
    const bake=bakeOwnership(source,canonical.startMs,canonical.endMs,canonical.cinematic!.performance.fps,actorBreakpoints,resolve);
    result.set(source.partId,{version:OWNERSHIP_RENDER_VERSION,source,paint,bake,aliases,shotHash:hash(canonical),sourceHash:hash({source,original,voice}),paintHash:hash(paint),motionVerified:false,productionApproval:false});
  }
  return result;
}

export const ownershipRenderDescription={version:OWNERSHIP_RENDER_VERSION,status:'candidate',
  geometry:'single entity from original ownership; shared palms agree, boundaries checked before interpolation; own original actor compiler breakpoints and a common original fps clock',
  paint:'explicit ownershipPaint for each entity and own original grip; own authored normalized viewport grip anchor matches physical stage offset; entity behind/in front of actors, each palm before/after entity; no inference from left/right, near/far or camera primary',
  interpolation:'measured sampled spatial error <=0.2px at interval probes; discrete grip/authority never tween; bounded refinement fails closed',
  pending:['actual source geometry/bake/SVG/runtime and film acceptance','camera/interaction/coverage/continuity/publication/review/QC integration and complete production audit','rotating tools/airborne drops and full faithful art/motion/input/voice/resume/final acceptance'],
  productionBinding:'needs-source-prop-binding',approved:false,productionReady:false,motionVerified:false,productionApproval:false};

import {
  SourceOwnershipSchema,
  type SourceOwnership,
  type OwnershipPhase,
} from './source-ownership-schemas.js';
import { ownershipPhaseAt } from './source-ownership-projection.js';

export interface OwnershipBakeSample {
  timeMs: number;
  center: { x: number; y: number };
  palms: Record<string, { x: number; y: number }>;
  activeGripIds: string[];
  authorityGripId?: string;
}

export interface OwnershipBake {
  version: 'ownership-bake-1';
  startMs: number;
  endMs: number;
  samples: OwnershipBakeSample[];
  maxMeasuredGapPx: number;
  gapLimitPx: 0.2;
  motionVerified: false;
  productionApproval: false;
}

type Point = { x: number; y: number };

const GAP_LIMIT_PX = 0.2;
const MAX_REFINEMENT_DEPTH = 12;
const MAX_FRAME_COUNT = 12000;
const PROBE_FRACTIONS: readonly number[] = [0.17, 0.5, 0.83];

function fail(message: string): never {
  throw new Error(`needs-source-prop-binding: ownership bake candidate: ${message}`);
}

function requireRecord(value: unknown, label: string): object {
  if (typeof value !== 'object' || value === null || Array.isArray(value)) {
    fail(`${label} must be a non-array object`);
  }
  return value;
}

/** Never read a dynamic palm key through an object's prototype or an accessor. */
function ownEnumerableData(record: object, key: string, label: string): unknown {
  const descriptor = Object.getOwnPropertyDescriptor(record, key);
  if (descriptor === undefined || descriptor.enumerable !== true
    || !Object.prototype.hasOwnProperty.call(descriptor, 'value')) {
    fail(`${label} must be an own enumerable data property`);
  }
  return descriptor.value;
}

function finiteNumber(value: unknown, label: string): number {
  if (typeof value !== 'number' || !Number.isFinite(value)) {
    fail(`${label} must be a finite number`);
  }
  return value;
}

function copyPoint(value: unknown, label: string): Point {
  const point = requireRecord(value, label);
  return {
    x: finiteNumber(ownEnumerableData(point, 'x', `${label}.x`), `${label}.x`),
    y: finiteNumber(ownEnumerableData(point, 'y', `${label}.y`), `${label}.y`),
  };
}

/** Copy only validated data; never repair a resolver's geometry or ownership. */
function copyResolvedSample(
  value: unknown,
  requestedTimeMs: number,
  gripIds: readonly string[],
  gripIdSet: ReadonlySet<string>,
  phase: OwnershipPhase,
): OwnershipBakeSample {
  const record = requireRecord(value, 'resolved sample');
  const timeMs = finiteNumber(
    ownEnumerableData(record, 'timeMs', 'sample.timeMs'),
    'sample.timeMs',
  );
  if (!Object.is(timeMs, requestedTimeMs)) {
    fail('resolver must return the exact requested global time, without tolerance or coercion');
  }

  const center = copyPoint(
    ownEnumerableData(record, 'center', 'sample.center'),
    'sample.center',
  );
  const rawPalms = requireRecord(
    ownEnumerableData(record, 'palms', 'sample.palms'),
    'sample.palms',
  );
  const palmKeys = Reflect.ownKeys(rawPalms);
  if (palmKeys.length !== gripIds.length) {
    fail('palms must contain exactly all original grip IDs, including inactive grips');
  }
  for (const key of palmKeys) {
    if (typeof key !== 'string' || !gripIdSet.has(key)) {
      fail('palms contains an undeclared key');
    }
  }

  // Null-prototype storage is essential: __proto__, constructor and similar
  // strings remain data keys. An inherited or accessor __proto__ is rejected
  // by ownEnumerableData, just like every other grip key.
  const palms = Object.create(null) as Record<string, Point>;
  for (const id of gripIds) {
    palms[id] = copyPoint(
      ownEnumerableData(rawPalms, id, `sample.palms[${id}]`),
      `sample.palms[${id}]`,
    );
  }

  const expectedActive: readonly string[] = phase.kind === 'world' ? []
    : phase.kind === 'held' ? [phase.gripId] : phase.gripIds;
  const rawActive = ownEnumerableData(record, 'activeGripIds', 'sample.activeGripIds');
  if (!Array.isArray(rawActive) || rawActive.length !== expectedActive.length) {
    fail('activeGripIds does not match the exact original phase');
  }
  const activeGripIds: string[] = [];
  const seenActive = new Set<string>();
  for (let index = 0; index < rawActive.length; index += 1) {
    const id = ownEnumerableData(rawActive, String(index), `sample.activeGripIds[${index}]`);
    if (typeof id !== 'string' || !gripIdSet.has(id)) {
      fail('activeGripIds contains a non-string or undeclared grip ID');
    }
    if (seenActive.has(id)) fail('activeGripIds contains a duplicate grip ID');
    if (!expectedActive.includes(id)) {
      fail('activeGripIds contains a grip that is inactive in the original phase');
    }
    seenActive.add(id);
    activeGripIds.push(id);
  }
  // Active IDs are an exact set, not a ranking. Preserve the resolver's order;
  // do not sort, replace or synthesize the supplied IDs.
  for (const id of expectedActive) {
    if (!seenActive.has(id)) fail('activeGripIds is missing an original active grip');
  }

  const authorityDescriptor = Object.getOwnPropertyDescriptor(record, 'authorityGripId');
  let suppliedAuthority: unknown = undefined;
  if (authorityDescriptor !== undefined) {
    suppliedAuthority = ownEnumerableData(record, 'authorityGripId', 'sample.authorityGripId');
  } else if ('authorityGripId' in record) {
    fail('authorityGripId must not be inherited');
  }
  const expectedAuthority = phase.kind === 'world' ? undefined
    : phase.kind === 'held' ? phase.gripId : phase.authorityGripId;
  if (suppliedAuthority !== expectedAuthority) {
    fail('authorityGripId does not match the exact original phase');
  }

  const copied: OwnershipBakeSample = { timeMs, center, palms, activeGripIds };
  if (typeof suppliedAuthority === 'string') {
    copied.authorityGripId = suppliedAuthority;
  }
  return copied;
}

/** Avoid overflowing b - a for finite coordinates of opposite signs. */
function interpolateCoordinate(a: number, b: number, fraction: number): number {
  const value = (a < 0) !== (b < 0)
    ? (1 - fraction) * a + fraction * b
    : a + (b - a) * fraction;
  if (!Number.isFinite(value)) fail('interpolated geometry is not finite');
  return value;
}

function pointInterpolationGap(
  left: Point,
  right: Point,
  actual: Point,
  fraction: number,
): number {
  const x = interpolateCoordinate(left.x, right.x, fraction);
  const y = interpolateCoordinate(left.y, right.y, fraction);
  const gap = Math.hypot(actual.x - x, actual.y - y);
  if (!Number.isFinite(gap)) fail('measured interpolation gap is not finite');
  return gap;
}

/** Only continuous geometry participates. No discrete ownership is tweened. */
function geometryInterpolationGap(
  left: OwnershipBakeSample,
  right: OwnershipBakeSample,
  actual: OwnershipBakeSample,
  gripIds: readonly string[],
): number {
  // Use the actual representable probe time, not its nominal fraction, when
  // evaluating the line between the two retained global-time samples.
  const fraction = (actual.timeMs - left.timeMs) / (right.timeMs - left.timeMs);
  if (!Number.isFinite(fraction) || fraction <= 0 || fraction >= 1) {
    fail('probe has no distinct representable interior interpolation fraction');
  }
  let gap = pointInterpolationGap(left.center, right.center, actual.center, fraction);
  for (const id of gripIds) {
    gap = Math.max(gap, pointInterpolationGap(
      left.palms[id]!, right.palms[id]!, actual.palms[id]!, fraction,
    ));
  }
  return gap;
}

/**
 * CANDIDATE source proposal: all clocks remain GLOBAL and original.
 *
 * The parent supplies its actual resolver, complete original actor/compiler
 * breakpoints, and independent original geometry/contact/boundary validation.
 * This module does not establish contact, continuity, native registration,
 * one-entity integration, motion acceptance or production approval.
 *
 * Discrete sample fields annotate their exact times. Consumers must retain the
 * original half-open phase semantics rather than interpolate those fields.
 * The original source's terminal time selects its final phase.
 *
 * maxMeasuredGapPx covers only the three probes of each final retained
 * interval. It is sampled interpolation candidate evidence, not a proof of
 * continuous correctness between probes.
 *
 * The conservative 12000-frame budget includes every distinct resolved time,
 * including probe-only records. Only mandatory and refinement times are
 * emitted. Failed validation, exhausted budgets or indistinct double times
 * throw; no partial bake or fallback is returned.
 */
export function bakeOwnership(
  source: SourceOwnership,
  startMs: number,
  endMs: number,
  fps: number,
  extraTimes: readonly number[],
  resolve: (globalTimeMs: number) => OwnershipBakeSample,
): OwnershipBake {
  // Structural validation preserves the complete original source. It does
  // not replace the parent's source/actor/contact/transition context gates.
  const original = SourceOwnershipSchema.parse(source);
  if (typeof startMs !== 'number' || typeof endMs !== 'number'
    || !Number.isFinite(startMs) || !Number.isFinite(endMs)
    || endMs <= startMs || startMs < original.startMs || endMs > original.endMs) {
    fail('the complete selected clock must be positive and inside the original source');
  }
  if (typeof fps !== 'number' || !Number.isFinite(fps) || fps <= 0 || fps > 120) {
    fail('fps must be finite, positive and at most 120');
  }
  if (!Array.isArray(extraTimes)) fail('extraTimes must be an array of original global times');
  if (typeof resolve !== 'function') fail('an explicit actual parent resolver is required');

  // Validate and snapshot ALL supplied breakpoints before filtering any of
  // them to the slice, and before making any resolver request.
  const validatedExtraTimes: number[] = [];
  for (let index = 0; index < extraTimes.length; index += 1) {
    const timeMs = finiteNumber(extraTimes[index], `extraTimes[${index}]`);
    if (timeMs < original.startMs || timeMs > original.endMs) {
      fail(`extraTimes[${index}] is outside the full original source`);
    }
    validatedExtraTimes.push(timeMs);
  }

  const gripIds = original.grips.map(grip => grip.id);
  const gripIdSet = new Set<string>(gripIds);
  // Map values preserve the first supplied numeric representation, including
  // a possible -0 endpoint; keys deduplicate coincident numeric times.
  const mandatory = new Map<number, number>();
  function addMandatory(timeMs: number): void {
    if (!Number.isFinite(timeMs) || timeMs < startMs || timeMs > endMs) {
      fail('internal mandatory time is outside the selected global clock');
    }
    if (mandatory.has(timeMs)) return;
    if (mandatory.size >= MAX_FRAME_COUNT) fail('mandatory times exceed the 12000-frame cap');
    mandatory.set(timeMs, timeMs);
  }

  addMandatory(startMs);
  addMandatory(endMs);
  for (const phase of original.phases) {
    if (phase.startMs >= startMs && phase.startMs <= endMs) addMandatory(phase.startMs);
    if (phase.endMs >= startMs && phase.endMs <= endMs) addMandatory(phase.endMs);
  }
  for (const timeMs of validatedExtraTimes) {
    if (timeMs >= startMs && timeMs <= endMs) addMandatory(timeMs);
  }

  // GLOBAL grid definition: original.startMs + (k * 1000) / fps, k >= 0.
  // Calculate each point independently; a camera cut never restarts the grid.
  // Scan one neighboring index on either side of the estimated index range
  // to handle floating-point rounding at the slice endpoints. Filtering never
  // changes a grid value or moves a supplied time onto the grid.
  const firstEstimate = Math.floor(((startMs - original.startMs) * fps) / 1000);
  const lastEstimate = Math.ceil(((endMs - original.startMs) * fps) / 1000);
  const firstIndex = firstEstimate > 0 ? firstEstimate - 1 : 0;
  const lastIndex = lastEstimate + 1;
  if (!Number.isSafeInteger(firstIndex) || !Number.isSafeInteger(lastIndex)) {
    fail('global fps-grid indices are not safely representable');
  }
  let previousGridTime: number | undefined;
  for (let index = firstIndex; index <= lastIndex; index += 1) {
    const timeMs = original.startMs + (index * 1000) / fps;
    // A tiny positive fps can put the first positive grid index at infinity.
    // No such index can lie inside the finite original source; later indices
    // cannot return to it. This is not a replacement or clamping of a time.
    if (!Number.isFinite(timeMs)) break;
    if (previousGridTime !== undefined && timeMs <= previousGridTime) {
      fail('global fps-grid times are not distinct increasing doubles');
    }
    previousGridTime = timeMs;
    if (timeMs > endMs) break;
    if (timeMs >= startMs) addMandatory(timeMs);
  }

  const orderedTimes = Array.from(mandatory.values()).sort((a, b) => a - b);
  const cache = new Map<number, OwnershipBakeSample>();
  function resolvedAt(timeMs: number): OwnershipBakeSample {
    if (!Number.isFinite(timeMs) || timeMs < startMs || timeMs > endMs) {
      fail('internal resolver request is outside the selected global clock');
    }
    const cached = cache.get(timeMs);
    if (cached !== undefined) {
      if (!Object.is(cached.timeMs, timeMs)) fail('cached time representation does not match the request');
      return cached;
    }
    if (cache.size >= MAX_FRAME_COUNT) {
      fail('distinct resolved frames, including probes, exceed the 12000-frame cap');
    }
    const phase = ownershipPhaseAt(original, timeMs);
    const copied = copyResolvedSample(resolve(timeMs), timeMs, gripIds, gripIdSet, phase);
    cache.set(timeMs, copied);
    return copied;
  }

  const samples: OwnershipBakeSample[] = [resolvedAt(orderedTimes[0]!)];
  let maxMeasuredGapPx = 0;

  function refine(
    left: OwnershipBakeSample,
    right: OwnershipBakeSample,
    depth: number,
  ): void {
    const durationMs = right.timeMs - left.timeMs;
    if (!Number.isFinite(durationMs) || durationMs <= 0) {
      fail('interval endpoints are not distinct increasing finite times');
    }

    const probeTimes: number[] = [];
    let previousTimeMs = left.timeMs;
    for (const fraction of PROBE_FRACTIONS) {
      const timeMs = left.timeMs + durationMs * fraction;
      if (!Number.isFinite(timeMs) || timeMs <= previousTimeMs || timeMs >= right.timeMs) {
        fail('interval is too small for distinct .17/.5/.83 double-time probes');
      }
      probeTimes.push(timeMs);
      previousTimeMs = timeMs;
    }

    const probes: OwnershipBakeSample[] = [];
    let intervalGapPx = 0;
    for (const timeMs of probeTimes) {
      const actual = resolvedAt(timeMs);
      probes.push(actual);
      intervalGapPx = Math.max(
        intervalGapPx,
        geometryInterpolationGap(left, right, actual, gripIds),
      );
    }

    if (intervalGapPx <= GAP_LIMIT_PX) {
      // Rejected coarse-interval errors are intentionally not reported as the
      // maximum error of the final, refined piecewise-linear candidate.
      maxMeasuredGapPx = Math.max(maxMeasuredGapPx, intervalGapPx);
      if (samples.length >= MAX_FRAME_COUNT) fail('retained samples exceed the 12000-frame cap');
      samples.push(right);
      return;
    }
    if (depth >= MAX_REFINEMENT_DEPTH) {
      fail('spatial interpolation error still exceeds 0.2px at refinement depth 12');
    }

    // The .5 record was already resolved, validated and cached. Split only at
    // this exact midpoint; do not move geometry, ownership or source events.
    const midpoint = probes[1]!;
    refine(left, midpoint, depth + 1);
    refine(midpoint, right, depth + 1);
  }

  for (let index = 1; index < orderedTimes.length; index += 1) {
    const left = resolvedAt(orderedTimes[index - 1]!);
    const right = resolvedAt(orderedTimes[index]!);
    refine(left, right, 0);
  }

  return {
    version: 'ownership-bake-1',
    startMs,
    endMs,
    samples,
    maxMeasuredGapPx,
    gapLimitPx: 0.2,
    motionVerified: false,
    productionApproval: false,
  };
}

import { z } from 'zod';
import { Id } from '../core/identifiers.js';
import { SourceRefSchema } from '../explainer/schemas.js';

/** CANDIDATE only: one canonical entity identified by id/partId.
 * Grip propIds are actor-owned source aliases, not additional entities.
 * No registration, pose, narration, geometry or production approval is implied.
 */
const Time = z.number().finite().int().nonnegative().max(Number.MAX_SAFE_INTEGER);
const StagePoint = z.object({ x: z.number().finite(), y: z.number().finite() }).strict();
const Interval = { startMs: Time, endMs: Time };
const EvidenceText = z.string().min(1).max(4096)
  .refine(value => /\S/.test(value), 'Evidence text must not be blank');
const Operation = z.enum(['pickup', 'place', 'handoff', 'join', 'release']);

const OwnershipGripSchema = z.object({
  id: Id,
  actorId: Id,
  sourceId: Id,
  gestureId: Id,
  propId: Id,
  hand: z.enum(['left', 'right']),
  // Explicit STAGE-pixel offset; never converted or inferred here.
  gripOffset: StagePoint,
}).strict();

const OwnershipPhaseSchema = z.discriminatedUnion('kind', [
  z.object({
    ...Interval, kind: z.literal('world'),
    center: StagePoint, rotationDeg: z.number().finite(),
  }).strict(),
  z.object({
    ...Interval, kind: z.literal('held'), gripId: Id,
  }).strict(),
  z.object({
    ...Interval, kind: z.literal('shared'),
    gripIds: z.tuple([Id, Id]), authorityGripId: Id,
  }).strict(),
]);

const TransitionSchema = z.object({
  id: Id,
  timeMs: Time,
  sourceRefs: z.array(SourceRefSchema).min(1).max(32),
  narrationAnchor: Id,
  statement: EvidenceText,
  operation: Operation,
}).strict();

export type OwnershipGrip = z.infer<typeof OwnershipGripSchema>;
export type OwnershipPhase = z.infer<typeof OwnershipPhaseSchema>;
type OwnershipOperation = z.infer<typeof Operation>;

/** Validate an explicitly supplied operation; do not choose one for the author.
 * A handoff boundary must touch positive-duration, two-person shared contact.
 */
function operationFits(a: OwnershipPhase, b: OwnershipPhase, operation: OwnershipOperation): boolean {
  if (a.kind === 'world' && b.kind === 'held') return operation === 'pickup';
  if (a.kind === 'held' && b.kind === 'world') return operation === 'place';
  if (a.kind === 'held' && b.kind === 'shared') {
    return b.gripIds.includes(a.gripId) && (operation === 'join' || operation === 'handoff');
  }
  if (a.kind === 'shared' && b.kind === 'held') {
    return a.gripIds.includes(b.gripId) && (operation === 'release' || operation === 'handoff');
  }
  if (a.kind === 'shared' && b.kind === 'shared') {
    return a.gripIds.every(id => b.gripIds.includes(id))
      && a.authorityGripId !== b.authorityGripId && operation === 'handoff';
  }
  // No exclusive-owner swap, world/shared shortcut or unregistered boundary.
  return false;
}

/** All times are in the original global clock, never relative to a camera slice.
 * Transitions are exactly the internal boundaries between consecutive phases.
 * Source endpoints do not imply events outside the declared history.
 */
export const SourceOwnershipSchema = z.object({
  version: z.literal('source-ownership-1'),
  id: Id,
  partId: Id,
  startMs: Time,
  endMs: Time,
  grips: z.array(OwnershipGripSchema).min(1).max(64),
  phases: z.array(OwnershipPhaseSchema).min(1).max(256),
  transitions: z.array(TransitionSchema).max(255),
}).strict().superRefine((source, ctx) => {
  const issue = (path: (string | number)[], message: string): void => {
    ctx.addIssue({ code: 'custom', path, message });
  };
  if (source.endMs <= source.startMs) issue(['endMs'], 'Original ownership span must be positive');

  // Declaration IDs are unique within this timeline; reference IDs may repeat.
  const declaredIds = new Set<string>([source.id]);
  const registerId = (id: string, path: (string | number)[]): void => {
    if (declaredIds.has(id)) issue(path, 'Duplicate ownership declaration ID');
    declaredIds.add(id);
  };
  const grips = new Map<string, OwnershipGrip>();
  const physicalAliases = new Set<string>();
  source.grips.forEach((grip, index) => {
    registerId(grip.id, ['grips', index, 'id']);
    grips.set(grip.id, grip);
    const alias=JSON.stringify([grip.actorId,grip.propId]);
    if(physicalAliases.has(alias))issue(['grips',index], 'One physical actor/prop alias cannot have multiple grip declarations');
    physicalAliases.add(alias);
  });

  const used = new Set<string>();
  let expectedStart = source.startMs;
  source.phases.forEach((phase, index) => {
    const path = ['phases', index];
    if (phase.startMs !== expectedStart) {
      issue([...path, 'startMs'], 'Phases must be ordered, contiguous and fully cover the original span');
    }
    if (phase.endMs <= phase.startMs || phase.startMs < source.startMs || phase.endMs > source.endMs) {
      issue(path, 'Phase must be positive and contained in the original span');
    }
    expectedStart = phase.endMs;

    const ids: readonly string[] = phase.kind === 'world' ? []
      : phase.kind === 'held' ? [phase.gripId] : phase.gripIds;
    const active: OwnershipGrip[] = [];
    for (const id of ids) {
      used.add(id);
      const grip = grips.get(id);
      if (!grip) {
        issue(path, `Unknown grip ID: ${id}`);
        continue;
      }
      if (active.some(other => other.actorId === grip.actorId && other.hand === grip.hand && other.id !== grip.id)) {
        issue(path, 'One actor/hand cannot simultaneously use different grip aliases');
      }
      active.push(grip);
    }
    if (phase.kind === 'shared') {
      if (phase.gripIds[0] === phase.gripIds[1]) issue([...path, 'gripIds'], 'Shared grip IDs must be distinct');
      if (!phase.gripIds.includes(phase.authorityGripId)) {
        issue([...path, 'authorityGripId'], 'Shared authority must explicitly name one of its two grips');
      }
      const first = grips.get(phase.gripIds[0]);
      const second = grips.get(phase.gripIds[1]);
      if (first && second && first.actorId === second.actorId) {
        issue([...path, 'gripIds'], 'Shared contact requires two different people');
      }
    }
  });
  if (expectedStart !== source.endMs) issue(['phases'], 'Phases must end at the original endMs');
  source.grips.forEach((grip, index) => {
    if (!used.has(grip.id)) issue(['grips', index], 'Unused grip alias');
    const active=source.phases.map((phase,i)=>({phase,i})).filter(({phase})=>phase.kind==='held'?phase.gripId===grip.id:phase.kind==='shared'&&phase.gripIds.includes(grip.id));
    if(active.some((a,i)=>i>0&&a.i!==active[i-1]!.i+1))issue(['grips',index], 'A released original grip cannot be reused; another attachment requires its own physical source alias');
  });

  if (source.transitions.length !== Math.max(0, source.phases.length - 1)) {
    issue(['transitions'], 'Exactly one transition is required at every internal phase boundary');
  }
  source.transitions.forEach((transition, index) => {
    const path = ['transitions', index];
    registerId(transition.id, [...path, 'id']);
    const before = source.phases[index];
    const after = source.phases[index + 1];
    if (!before || !after) {
      issue(path, 'Transition has no corresponding internal phase boundary');
      return;
    }
    if (transition.timeMs !== before.endMs || transition.timeMs !== after.startMs) {
      issue([...path, 'timeMs'], 'Transition must match its original phase boundary in source order');
    }
    if (!operationFits(before, after, transition.operation)) {
      issue([...path, 'operation'], 'Operation does not describe a supported contact boundary with real shared overlap for handoff');
    }
  });
});

export type SourceOwnership = z.infer<typeof SourceOwnershipSchema>;

